// FilmsGridCount says "{count, plural, one {# film} other {# films}}"
// in the language the app shows under cx.
//
// Dimmed note beside the grid's heading: how many films it holds.
func FilmsGridCount(cx *core.Scope, count int) string { return For(cx).FilmsGridCount(count) }

// FilmsGridCount is the package's FilmsGridCount in the language of msgs.
func (msgs Messages) FilmsGridCount(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.FilmsGridCount(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].FilmsGridCount; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" film")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" films")
			}
			return b.String()
		case "ja":
			return i18n.FormatNumber("ja", float64(count)) + " 本"
		case "ko":
			return i18n.FormatNumber("ko", float64(count)) + "편"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 部"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 部"
		}
	}
}

