// FilmsUntranslated says "{count, plural, one {# line} other {# lines}} failed to translate, the rest are done"
// in the language the app shows under cx.
//
// Part of the line under a finished film: how many subtitle lines the translation failed on.
func FilmsUntranslated(cx *core.Scope, count int) string { return For(cx).FilmsUntranslated(count) }

// FilmsUntranslated is the package's FilmsUntranslated in the language of msgs.
func (msgs Messages) FilmsUntranslated(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.FilmsUntranslated(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].FilmsUntranslated; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" line")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" lines")
			}
			b.WriteString(" failed to translate, the rest are done")
			return b.String()
		case "ja":
			return i18n.FormatNumber("ja", float64(count)) + " 行の翻訳に失敗、残りは完了"
		case "ko":
			return "대사 " + i18n.FormatNumber("ko", float64(count)) + "개 번역 실패, 나머지는 완료"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 句翻译失败，其余已完成"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 句翻譯失敗，其餘已完成"
		}
	}
}

