// MenuRevealLibrary says "{platform, select, macOS {Show Library in Finder} Windows {Show Library in File Explorer} other {Show Library in File Manager}}"
// in the language the app shows under cx.
//
// File menu item that shows the open library's folder in the system's file manager. {platform} is the system the app runs on: macOS, Windows or another (Linux); each case names that system's file manager.
func MenuRevealLibrary(cx *core.Scope, platform string) string {
	return For(cx).MenuRevealLibrary(platform)
}

// MenuRevealLibrary is the package's MenuRevealLibrary in the language of msgs.
func (msgs Messages) MenuRevealLibrary(platform string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.MenuRevealLibrary(platform))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].MenuRevealLibrary; f != nil {
			return f(platform)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("Show Library in Finder")
			case "Windows":
				b.WriteString("Show Library in File Explorer")
			default:
				b.WriteString("Show Library in File Manager")
			}
			return b.String()
		case "ja":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("ライブラリを Finder で表示")
			case "Windows":
				b.WriteString("ライブラリをエクスプローラーで表示")
			default:
				b.WriteString("ライブラリをファイルマネージャーで表示")
			}
			return b.String()
		case "ko":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("Finder에서 라이브러리 보기")
			case "Windows":
				b.WriteString("파일 탐색기에서 라이브러리 보기")
			default:
				b.WriteString("파일 관리자에서 라이브러리 보기")
			}
			return b.String()
		case "zh-Hans":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("在访达中显示资料库")
			case "Windows":
				b.WriteString("在文件资源管理器中显示资料库")
			default:
				b.WriteString("在文件管理器中显示资料库")
			}
			return b.String()
		case "zh-Hant":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("在 Finder 中顯示資料庫")
			case "Windows":
				b.WriteString("在檔案總管中顯示資料庫")
			default:
				b.WriteString("在檔案管理員中顯示資料庫")
			}
			return b.String()
		}
	}
}

