// SettingsLibrarySaveFailed says "Couldn't save the library: {error}"
// in the language the app shows under cx.
//
// Error when the libraries could not be saved to settings.json.
func SettingsLibrarySaveFailed(cx *core.Scope, error_ string) string {
	return For(cx).SettingsLibrarySaveFailed(error_)
}

// SettingsLibrarySaveFailed is the package's SettingsLibrarySaveFailed in the language of msgs.
func (msgs Messages) SettingsLibrarySaveFailed(error_ string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.SettingsLibrarySaveFailed(error_))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].SettingsLibrarySaveFailed; f != nil {
			return f(error_)
		}
		switch lang {
		case "", "en":
			return "Couldn't save the library: " + msgs.arg(error_)
		case "ja":
			return "ライブラリを保存できません：" + error_
		case "ko":
			return "라이브러리를 저장할 수 없습니다: " + error_
		case "zh-Hans":
			return "资料库无法保存：" + error_
		case "zh-Hant":
			return "資料庫無法儲存：" + error_
		}
	}
}

