// SettingsSpeechDownloadFailedStatus says "The server answered HTTP {status}. Try again later."
// in the language the app shows under cx.
//
// Error on the Speech Recognition page and in the guide: the server answered a whisper model's download with an error status.
func SettingsSpeechDownloadFailedStatus(cx *core.Scope, status int) string {
	return For(cx).SettingsSpeechDownloadFailedStatus(status)
}

// SettingsSpeechDownloadFailedStatus is the package's SettingsSpeechDownloadFailedStatus in the language of msgs.
func (msgs Messages) SettingsSpeechDownloadFailedStatus(status int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.SettingsSpeechDownloadFailedStatus(status))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].SettingsSpeechDownloadFailedStatus; f != nil {
			return f(status)
		}
		switch lang {
		case "", "en":
			return "The server answered HTTP " + msgs.arg(i18n.FormatNumber("en", float64(status))) + ". Try again later."
		case "ja":
			return "サーバーが HTTP " + i18n.FormatNumber("ja", float64(status)) + " を返しました。しばらくしてからもう一度お試しください。"
		case "ko":
			return "서버가 HTTP " + i18n.FormatNumber("ko", float64(status)) + " 오류를 반환했습니다. 잠시 후 다시 시도하세요."
		case "zh-Hans":
			return "服务器返回 HTTP " + i18n.FormatNumber("zh-Hans", float64(status)) + "，请稍后再试。"
		case "zh-Hant":
			return "伺服器回傳 HTTP " + i18n.FormatNumber("zh-Hant", float64(status)) + "，請稍後再試。"
		}
	}
}

// SettingsSpeechDownloadFailedStatusMirror says "Hugging Face answered HTTP {status}. Try again later, or download from hf-mirror.com."
// in the language the app shows under cx.
//
// Error on the Speech Recognition page and in the guide: Hugging Face answered a whisper model's download with an error status, as it does where it is blocked. hf-mirror.com is a mirror of Hugging Face; the error is shown next to the button that downloads the model from there (settingsSpeechDownloadFromMirror). Keep hf-mirror.com and Hugging Face as they are.
func SettingsSpeechDownloadFailedStatusMirror(cx *core.Scope, status int) string {
	return For(cx).SettingsSpeechDownloadFailedStatusMirror(status)
}

// SettingsSpeechDownloadFailedStatusMirror is the package's SettingsSpeechDownloadFailedStatusMirror in the language of msgs.
